#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/")
`%||%`<-function(left,right)if(is.null(left)||!length(left))right else left;source(file.path(root,"app/shiny/R/project_discovery.R"));source(file.path(root,"app/shiny/R/fitness_result_state.R"));project<-read_project_summary(args[[1]],root)
result<-list(legacy=FALSE,cache_signature="abc",selected_comparisons=c("a","b"),status="success",table=tempfile(),analysis_id="x");legacy<-within(result,{legacy<-TRUE;cache_signature<-""});historical<-within(result,{cache_signature<-"other"});incompatible<-within(result,{cache_signature<-"other";selected_comparisons<-"c"});failed<-within(result,{status<-"failed"})
stopifnot(resolve_fitness_result_state("a","abc",list(),FALSE)$status=="no_design",resolve_fitness_result_state(character(),"abc",list(result))$status=="no_selection",resolve_fitness_result_state("a","abc",list())$status=="no_result",resolve_fitness_result_state(c("a","b"),"abc",list(result))$status=="matching_completed_result",resolve_fitness_result_state(c("a","b"),"abc",list(historical))$status=="historical_result_only",resolve_fitness_result_state("a","abc",list(incompatible))$status=="incompatible_result",resolve_fitness_result_state("a","abc",list(legacy))$status=="legacy_result",resolve_fitness_result_state(c("a","b"),"abc",list(failed))$status=="failed_result",fitness_job_result_state("dry_run_success")=="preview_complete",fitness_job_result_state("failed")=="failed_result",fitness_job_result_state("success",TRUE)=="matching_cached_result",fitness_smoke_project(project))
cat("PASS\n")
